let DATA, CI, currentYear='2025', currentView='visao', slideIndex=0, timerSeconds=720, timerHandle=null;
const brl=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v);
const compact=v=>new Intl.NumberFormat('pt-BR',{notation:'compact',maximumFractionDigits:2}).format(v);
const pct=(v,d=1)=>`${v.toFixed(d).replace('.',',')}%`;
const brl4=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:4}).format(v);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const recorteCache=new Map();
function csvFields(line){let fields=[],value='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===';'&&!quoted){fields.push(value);value=''}else value+=c}fields.push(value);return fields}
function renderRecorteFunctions(){
  const year=el('#recorteYear').value,select=el('#recorteFunction'),previous=select.value;
  const functions=DATA.years[year].top.funcoes.slice().sort((a,b)=>a.label.localeCompare(b.label,'pt-BR'));
  select.innerHTML='<option value="">Todas as funções</option>'+functions.map(f=>`<option value="${safe(f.code)}">${safe(f.label)} · código ${safe(f.code)}</option>`).join('');
  if(functions.some(f=>f.code===previous))select.value=previous;
}
async function consultRecorte(){
  const year=el('#recorteYear').value,month=el('#recorteMonth').value,func=el('#recorteFunction').value,key=`${year}-${month}`;
  const status=el('#recorteStatus'),result=el('#recorteResult');status.textContent=`Carregando ${key} da base oficial…`;result.innerHTML='';el('#recorteApply').disabled=true;
  try{
    if(!recorteCache.has(key)){
      const response=await fetch(`recortes/${key}.csv`);if(!response.ok)throw new Error(`Arquivo ${key}.csv indisponível (${response.status})`);
      const lines=(await response.text()).trimEnd().split(/\r?\n/);
      if(lines.shift()!=='id;documento;funcao;orgao;valor_pago;arquivo')throw new Error('Cabeçalho do recorte inválido');
      recorteCache.set(key,lines.map(csvFields));
    }
    const allRows=recorteCache.get(key),monthTotal=allRows.reduce((sum,r)=>sum+Math.round(Number(r[4])*10000),0)/10000;
    const expected=DATA.years[year].months[month];
    if(allRows.length!==expected.rows||Math.abs(monthTotal-expected.pago)>.02)throw new Error('O índice de registros não concilia com o indicador mensal; recorte bloqueado');
    const rows=func?allRows.filter(r=>r[2]===func):allRows;
    const cents4=rows.reduce((sum,r)=>sum+Math.round(Number(r[4])*10000),0),amount=cents4/10000;
    const negative=rows.filter(r=>Number(r[4])<0).length;
    const label=func?el('#recorteFunction').selectedOptions[0].textContent:'Todas as funções';
    status.textContent=`${year}/${month} · ${label} · ${rows.length.toLocaleString('pt-BR')} registros · índice mensal conciliado com o indicador.`;
    if(!rows.length){result.innerHTML='<div class="recorte-empty">Nenhum registro corresponde a este filtro. Altere o mês ou a função.</div>';return}
    const body=rows.slice(0,25).map(r=>`<tr><td>${safe(r[0])}</td><td>${safe(r[1])}</td><td>${safe(r[2])}</td><td>${safe(r[3])}</td><td>${brl4(Number(r[4]))}</td><td>${safe(r[5])}</td></tr>`).join('');
    result.innerHTML=`<div class="recorte-summary"><div><small>VALOR PAGO LÍQUIDO</small><strong>${brl4(amount)}</strong></div><div><small>REGISTROS</small><strong>${rows.length.toLocaleString('pt-BR')}</strong></div><div><small>VALORES NEGATIVOS</small><strong>${negative.toLocaleString('pt-BR')}</strong></div></div><p class="recorte-note">Soma de ValorPago (negativos preservados). A tabela mostra os 25 primeiros registros; o botão baixa todos os ${rows.length.toLocaleString('pt-BR')} IDs e valores deste recorte, sem dados pessoais. Fonte: oito ZIPs oficiais de despesas ES, agrupados por ano e mês.</p><button class="recorte-download" id="recorteDownload">Baixar recorte completo (CSV)</button><div class="table-wrap"><table><thead><tr><th>ID</th><th>Documento</th><th>Função</th><th>Órgão</th><th>ValorPago</th><th>ZIP de origem</th></tr></thead><tbody>${body}</tbody></table></div>`;
    el('#recorteDownload').onclick=()=>{const csv='id;documento;funcao;orgao;valor_pago;arquivo\n'+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(';')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`farol-es-recorte-${key}-${func||'todas'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
  }catch(error){status.textContent='Não foi possível consultar o recorte.';result.innerHTML=`<div class="recorte-error"><b>Consulta indisponível</b><p>${safe(error.message)}. Confirme que a POC está sendo servida por HTTP e que os arquivos foram gerados pelo pipeline.</p></div>`}
  finally{el('#recorteApply').disabled=false}
}
const el=(q,root=document)=>root.querySelector(q); const all=(q,root=document)=>[...root.querySelectorAll(q)];

async function init(){
  try{const r=await fetch('analysis.json');if(!r.ok)throw new Error('Falha ao carregar');DATA=await r.json();const ci=await fetch('ci_2025.json');CI=ci.ok?await ci.json():null;renderAll();bind();}
  catch(e){document.querySelector('main').innerHTML=`<section class="view active"><div class="empty-state"><strong>Não foi possível carregar a análise.</strong><p>Verifique se o arquivo analysis.json está disponível e tente novamente.</p></div></section>`;}
}
function sumRows(){return DATA.years['2024'].total.rows+DATA.years['2025'].total.rows}
function delta(a,b){return a?((b-a)/a*100):0}
function renderAll(){el('#recordCount').textContent=`${sumRows().toLocaleString('pt-BR')} registros`;renderKpis();renderMonthly();renderSignals();renderRanking();renderEvidence();renderCI();renderTraceOptions();renderTrace(DATA.years['2025'].topPayments[0]);renderQuality();renderFiles();renderTeam();renderRecorteFunctions();buildSlides();}
function renderCI(){const node=el('#ciResult');if(!CI){node.textContent='Demonstração indisponível: execute node pipeline/confidence_interval.js.';return}node.innerHTML=`<div class="ci-values"><div><small>Amostra aleatória reproduzível</small><strong>${CI.n.toLocaleString('pt-BR')}</strong><span>registros de 2025 · semente ${CI.seed}</span></div><div><small>Estimativa amostral de valores negativos</small><strong>${pct(CI.estimate*100,2)}</strong><span>IC 95% de Wilson: ${pct(CI.lower*100,2)} a ${pct(CI.upper*100,2)}</span></div><div><small>Valor exato da base integral</small><strong>${pct(CI.censusProportion*100,2)}</strong><span>${CI.negativePopulation.toLocaleString('pt-BR')} de ${CI.population.toLocaleString('pt-BR')} registros</span></div></div><p class="recorte-note">O intervalo é uma demonstração didática de inferência sobre amostra aleatória simples; não é a incerteza do total censitário, que foi calculado sobre todos os registros publicados. Ele não mede erro da fonte nem indica fraude.</p>`}
function renderKpis(){const a=DATA.years['2024'].total,b=DATA.years['2025'].total;let y=currentYear==='compare'?'2025':currentYear,s=DATA.years[y].total,other=DATA.years[y==='2025'?'2024':'2025'].total;const direction=y==='2025'?1:-1;const items=[['Pagamentos líquidos',brl(s.pago),`${pct(direction*delta(other.pago,s.pago))} vs. ${y==='2025'?'2024':'2025'}`,direction*delta(other.pago,s.pago)],['Registros processados',s.rows.toLocaleString('pt-BR'),`${(s.rows/sumRows()*100).toFixed(1).replace('.',',')}% da base`,0],['Valores negativos',s.negPaid.toLocaleString('pt-BR'),`${brl(s.paidNegativeAbs)} em estornos/correções`,0],['Favorecidos distintos',DATA.years[y].distinct.favorecidos.toLocaleString('pt-BR'),`HHI ${(DATA.years[y].hhiFavorecidos*10000).toFixed(0)} · concentração moderada`,0]];el('#kpiGrid').innerHTML=items.map(x=>`<div class="kpi"><span class="label">${x[0]}</span><strong>${x[1]}</strong><small class="${x[3]<0?'delta down':'delta'}">${x[2]}</small></div>`).join('')}
function renderMonthly(){const months=['01','02','03','04','05','06','07','08','09','10','11','12'],names=['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];const s24=months.map(m=>DATA.years['2024'].months[m].pago/1e9),s25=months.map(m=>DATA.years['2025'].months[m].pago/1e9),max=Math.max(...s24,...s25)*1.12,w=900,h=260,p={l:42,r:12,t:15,b:32};const x=i=>p.l+i*(w-p.l-p.r)/11,y=v=>p.t+(max-v)*(h-p.t-p.b)/max;const path=a=>a.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');let grid='';for(let i=0;i<=4;i++){const yy=p.t+i*(h-p.t-p.b)/4,val=max*(1-i/4);grid+=`<line class="gridline" x1="${p.l}" y1="${yy}" x2="${w-p.r}" y2="${yy}"/><text class="axis-label" x="0" y="${yy+4}">${val.toFixed(1).replace('.',',')} bi</text>`}const labels=names.map((n,i)=>`<text class="axis-label" x="${x(i)}" y="${h-5}" text-anchor="middle">${n}</text>`).join('');const pts=(a,c)=>a.map((v,i)=>`<circle class="${c}" cx="${x(i)}" cy="${y(v)}" r="3"><title>${names[i]}: R$ ${v.toFixed(2)} bi</title></circle>`).join('');el('#monthlyChart').setAttribute('viewBox',`0 0 ${w} ${h}`);el('#monthlyChart').innerHTML=`<defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#35d0ba" stop-opacity=".24"/><stop offset="1" stop-color="#35d0ba" stop-opacity="0"/></linearGradient></defs>${grid}<path class="area25" d="${path(s25)} L${x(11)},${h-p.b} L${x(0)},${h-p.b} Z"/><path class="line24" d="${path(s24)}"/><path class="line25" d="${path(s25)}"/>${pts(s24,'point24')}${pts(s25,'point25')}${labels}`;const peak=months.map((m,i)=>({m:names[i],d:s25[i]-s24[i]})).sort((a,b)=>b.d-a.d)[0];el('#monthlyInsight').textContent=`Maior avanço mensal em ${peak.m}: ${brl(peak.d*1e9)} acima de 2024. Dezembro concentra o maior volume nos dois anos.`}
function groupMap(y,dim){return Object.fromEntries(DATA.years[y].top[dim].map(x=>[x.code,x]))}
function renderSignals(){const f24=groupMap('2024','funcoes'),f25=groupMap('2025','funcoes');const codes=[...new Set([...Object.keys(f24),...Object.keys(f25)])];const rows=codes.map(c=>({label:(f25[c]||f24[c]).label,a:f24[c]?.metrics.pago||0,b:f25[c]?.metrics.pago||0})).map(x=>({...x,d:x.b-x.a,p:delta(x.a,x.b)})).sort((a,b)=>Math.abs(b.d)-Math.abs(a.d)).slice(0,4);el('#signals').innerHTML=rows.map((x,i)=>`<li><i>${String(i+1).padStart(2,'0')}</i><span>${safe(x.label)}</span><b>${x.d>=0?'+':''}${brl(x.d)} · ${x.p>=0?'+':''}${pct(x.p)}</b></li>`).join('')}
function renderRanking(){const y=el('#rankingYear').value,rows=DATA.years[y].top.funcoes.slice(0,8),max=rows[0].metrics.pago;el('#functionRanking').innerHTML=rows.map((x,i)=>`<div class="rank-row"><span class="num">${String(i+1).padStart(2,'0')}</span><span>${safe(x.label)}${y==='2025'?'<sup title="Rótulo recuperado pelo código de 2024">†</sup>':''}</span><div class="bar-track"><i style="width:${x.metrics.pago/max*100}%"></i></div><b>${compact(x.metrics.pago)}</b></div>`).join('')}
function renderEvidence(){const f24=groupMap('2024','funcoes'),f25=groupMap('2025','funcoes');const rows=['10','26','9'].map(c=>({label:(f25[c]||f24[c]).label,d:f25[c].metrics.pago-f24[c].metrics.pago}));const max=Math.max(...rows.map(x=>Math.abs(x.d)));el('#deltaBars').innerHTML=rows.map(x=>`<div class="delta-row"><span>${safe(x.label)}</span><div class="delta-track"><i style="width:${Math.abs(x.d)/max*100}%;background:${x.d<0?'#d28b27':''}"></i></div><b style="color:${x.d<0?'#9a5e00':''}">${x.d>=0?'+':''}${compact(x.d)}</b></div>`).join('')}
function traceRecords(){return [...DATA.years['2025'].topPayments.slice(0,10),...DATA.years['2024'].topPayments.slice(0,6)]}
function renderTraceOptions(){el('#traceSelect').innerHTML=traceRecords().map((r,i)=>`<option value="${i}">${safe(r.documento)} · ${brl(r.pago)}</option>`).join('')}
function resolvedLabel(r,key){if(r[key])return r[key];const dim=key==='orgao'?'orgaos':key==='funcao'?'funcoes':'elementos',code=r[key+'Code'];return (DATA.years['2024'].top[dim].find(x=>x.code===code)||DATA.years['2025'].top[dim].find(x=>x.code===code))?.label||`Código ${code}`}
function renderTrace(r){if(!r){el('#traceResult').innerHTML='<div class="empty-state"><strong>Registro não encontrado.</strong><p>A busca individual cobre somente exemplos dos maiores pagamentos; use o filtro de recorte para consultar todos os registros.</p></div>';return}el('#traceResult').innerHTML=`<div class="trace-hero"><div><span class="tag">REGISTRO OFICIAL · ${safe(r.year)}</span><h2>${safe(r.documento||'Documento não informado')}</h2><small>ID ${safe(r.id)} · ${safe(r.date)}</small></div><div class="trace-amount"><strong>${brl(r.pago)}</strong><small>valor pago líquido</small></div></div><div class="trace-grid"><div><span>Órgão</span><b>${safe(resolvedLabel(r,'orgao'))}</b></div><div><span>Função</span><b>${safe(resolvedLabel(r,'funcao'))} ${r.year==='2025'?'<sup>rótulo recuperado</sup>':''}</b></div><div><span>Elemento</span><b>${safe(resolvedLabel(r,'elemento'))}</b></div><div><span>Favorecido</span><b>${safe(r.favorecido)}</b></div><div><span>Licitação</span><b>${safe(r.tipoLicitacao||'não informada')}</b></div><div><span>Processo</span><b>${safe(r.processo||'não informado')}</b></div></div><div class="trace-history"><span class="tag amber">HISTÓRICO</span><p>${safe(r.history||'Histórico não informado na fonte.')}</p></div><div class="trail"><div><b>Fonte</b><br>CSV oficial</div><div><b>Ingestão</b><br>estrutura validada</div><div><b>Tratamento</b><br>moeda + rótulos</div><div><b>Indicador</b><br>soma líquida</div><div><b>Registro</b><br>${safe(r.documento)}</div></div>`}
function renderQuality(){const y24=DATA.years['2024'],y25=DATA.years['2025'];el('#qualityKpis').innerHTML=[['1.092.158','linhas processadas'],['0','linhas malformadas'],['0','IDs duplicados'],['71','campos por registro']].map(x=>`<div class="quality-card"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('');const fields=[['Orgao','Nome do órgão','Código íntegro; rótulo não publicado'],['Funcao','Nome da função','2025 recuperável por código'],['HistoricoDocumento','Histórico','ausência relevante e crescente'],['Favorecido','Favorecido','completo; PF protegida na interface'],['Id','ID do registro','chave completa e única']];el('#qualityTable').innerHTML=fields.map(([k,label,note])=>{const a=100*y24.qualityMissing[k]/y24.total.rows,b=100*y25.qualityMissing[k]/y25.total.rows;return`<tr><td><b>${label}</b></td><td class="${a>10?'bad':'good'}">${pct(a)}</td><td class="${b>10?'bad':'good'}">${pct(b)}</td><td>${note}</td></tr>`}).join('')}
function renderFiles(){el('#fileList').innerHTML=DATA.files.map(f=>`<li><span>${safe(f.file.replace('.zip',''))}</span><b>${f.rows.toLocaleString('pt-BR')} linhas</b></li>`).join('')}
function renderTeam(){const team=[['Dennis Nieto Generoso','RM 563671','Qualidade e testes'],['Francisco Nogueira De Queiroz','RM 566309','Frontend e acessibilidade'],['Mateus Nunes Araújo','RM 562008','Engenharia de dados'],['Matheus Henrique Ferreira Camargo da Silva','RM 566232','Produto e gestão'],['RHARIEL MARCELO DE OLIVEIRA PERMANHANI','RM 566310','Arquitetura e backend'],['Sara Marangon de Macedo','RM 563807','UX, pesquisa e apresentação']];el('#team').innerHTML=team.map(x=>`<div class="member"><b>${safe(x[0])}</b><span>${safe(x[1])}</span><small>${safe(x[2])}</small></div>`).join('')}
function showView(id){currentView=id;all('.view').forEach(v=>v.classList.toggle('active',v.id===id));all('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===id));history.replaceState(null,'','#'+id);scrollTo({top:0,behavior:'smooth'})}
function exportCsv(){const lines=[['ano','registros','empenhado','liquidado','pago_liquido','estornos_abs'],...['2024','2025'].map(y=>{const t=DATA.years[y].total;return[y,t.rows,t.empenho,t.liquidado,t.pago,t.paidNegativeAbs]})];const blob=new Blob([lines.map(r=>r.join(';')).join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='farol-es-resumo-2024-2025.csv';a.click();URL.revokeObjectURL(a.href)}
function bind(){all('.nav-btn').forEach(b=>b.onclick=()=>showView(b.dataset.view));all('[data-go]').forEach(b=>b.onclick=()=>showView(b.dataset.go));all('[data-year]').forEach(b=>b.onclick=()=>{all('[data-year]').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentYear=b.dataset.year;renderKpis()});el('#rankingYear').onchange=renderRanking;el('#recorteYear').onchange=renderRecorteFunctions;el('#recorteApply').onclick=consultRecorte;el('#traceSelect').onchange=e=>renderTrace(traceRecords()[+e.target.value]);el('#traceBtn').onclick=searchTrace;el('#traceInput').onkeydown=e=>{if(e.key==='Enter')searchTrace()};all('[data-example]').forEach(b=>b.onclick=()=>{el('#traceInput').value=b.dataset.example;searchTrace()});el('#exportBtn').onclick=exportCsv;el('#presentBtn').onclick=openPresentation;el('#closePresent').onclick=closePresentation;el('#nextSlide').onclick=()=>moveSlide(1);el('#prevSlide').onclick=()=>moveSlide(-1);el('#timerBtn').onclick=toggleTimer;document.addEventListener('keydown',e=>{if(el('#presentation').classList.contains('open')){if(['ArrowRight',' '].includes(e.key)){e.preventDefault();moveSlide(1)}if(e.key==='ArrowLeft')moveSlide(-1);if(e.key==='Escape')closePresentation()}else if(e.key.toLowerCase()==='p'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))openPresentation()});const hash=location.hash.slice(1);if(['visao','evidencias','rastrear','qualidade','projeto'].includes(hash))showView(hash)}
function searchTrace(){const q=el('#traceInput').value.trim().toLowerCase(),r=traceRecords().find(x=>x.id.toLowerCase()===q||x.documento.toLowerCase()===q);renderTrace(r)}
const slideData=[
  ['01 · DESAFIO','Transparência útil começa com uma pergunta concreta.','Farol ES ajuda jornalistas de dados a investigar pagamentos públicos, com contexto e caminho de volta à fonte.','Matheus · 0:00–1:00'],
  ['02 · DADOS E MÉTODO','Oito arquivos oficiais. 1.092.158 registros.','CSV em UTF-8 com BOM; separador ponto e vírgula; moeda decimal; ausências e estornos preservados e auditados.','Mateus · 1:00–2:00'],
  ['03 · QUESTÃO 1','O que mudou nos pagamentos entre 2024 e 2025?','Pagamento líquido: R$ 10,34 bi → R$ 11,28 bi (+9,1%). A comparação por função orientou o filtro investigativo.','Mateus · 2:00–3:00'],
  ['04 · QUESTÃO 2','Onde a publicação deixa lacunas?','O nome do órgão falta em ambos os anos; o nome da função falta em 2025. Os códigos seguem disponíveis e os rótulos recuperados são sinalizados.','Dennis · 3:00–4:00'],
  ['05 · DEMONSTRAÇÃO AO VIVO','Do indicador ao recorte completo, sem dados pessoais.','Filtrar ano, mês e função → conferir soma e contagem → examinar IDs → exportar o recorte → mostrar ausência e erro.','Francisco e Sara · 4:00–8:30'],
  ['06 · ENGENHARIA E EQUIPE','Uma POC pequena, funcional e reproduzível.','Pipeline Java em streaming; índice mensal minimizado; site acessível; seis responsáveis com entregáveis e testes.','Rhariel · 8:30–9:30'],
  ['07 · VIABILIDADE','16 semanas e custo simulado abaixo do teto.','Marcos com responsáveis, dependências e aceite. Investimento proposto de R$ 168.480; operação mensal estimada em R$ 8.900.','Matheus · 9:30–10:45'],
  ['08 · LIMITES E PRÓXIMO PASSO','Um sinal não é prova de irregularidade.','Riscos: qualidade, interpretação, privacidade e acesso. A banca pode reproduzir cada número e avaliar o que já funciona.','Sara e Dennis · 10:45–12:00']
];
function buildSlides(){el('#slideStage').innerHTML=slideData.map((s,i)=>`<section class="slide ${i===0?'active':''}"><span class="slide-kicker">${s[0]}</span><h2>${s[1]}</h2><p>${s[2]}</p>${i===2?'<div class="big-number">+9,1%</div>':''}${i===3?'<div class="slide-cards"><div><strong>100%</strong>órgão sem nome</div><div><strong>100%</strong>função 2025 sem nome</div><div><strong>0</strong>IDs duplicados</div></div>':''}<span class="speaker">${s[3]}</span></section>`).join('')}
function openPresentation(){el('#presentation').classList.add('open');el('#presentation').setAttribute('aria-hidden','false');slideIndex=0;showSlide()}
function closePresentation(){el('#presentation').classList.remove('open');el('#presentation').setAttribute('aria-hidden','true');if(timerHandle){clearInterval(timerHandle);timerHandle=null}}
function moveSlide(d){slideIndex=Math.max(0,Math.min(slideData.length-1,slideIndex+d));showSlide()}
function showSlide(){all('.slide').forEach((s,i)=>s.classList.toggle('active',i===slideIndex));el('#slideCounter').textContent=`${String(slideIndex+1).padStart(2,'0')} / ${slideData.length}`}
function toggleTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null;el('#timerBtn').textContent='Retomar';return}el('#timerBtn').textContent='Pausar';timerHandle=setInterval(()=>{timerSeconds--;const m=Math.max(0,Math.floor(timerSeconds/60)),s=Math.max(0,timerSeconds%60);el('#timerText').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;if(timerSeconds<=0){clearInterval(timerHandle);timerHandle=null}},1000)}
init();
